export function cropIntelligence(f,r){const missing=[];if(!['Mango Kent','Mango Haden','Limón Sutil'].includes(f.crop))missing.push('cultivo');if(!['poda','inducción floral','floración','cuajado','llenado de fruto'].includes(f.stage))missing.push('etapa');if(!['arenoso','franco arenoso','franco','arcilloso'].includes(f.soil))missing.push('suelo');if(r.missing.length)missing.push(...r.missing);if(missing.length)return {version:'crop-2.0',status:'DATOS INSUFICIENTES',missing};const sensitive=['floración','cuajado','llenado de fruto'].includes(f.stage),waterFactor=sensitive?.5:.3;const penalties=[{rule:'C1',reason:`Sensibilidad hídrica en ${f.stage}`,value:r.water*waterFactor},{rule:'C2',reason:'Condición térmica superficial',value:r.heat*.25},{rule:'C3',reason:'Condiciones de lluvia',value:r.rain*.15},{rule:'C4',reason:'Retención de agua supuesta por textura',value:['arenoso','franco arenoso'].includes(f.soil)?10:0}];return {version:'crop-2.0',status:'EXPERIMENTAL',crop:f.crop,stage:f.stage,score:Math.round(Math.max(0,100-penalties.reduce((s,p)=>s+p.value,0))),penalties,missing:[],limits:['Compatibilidad indicativa de manejo, no aptitud certificada ni rendimiento.','Coeficientes hipotéticos sin calibración local; Kent/Haden no tienen modelos varietales separados.','No utiliza T máxima del aire predicha como si fuera temperatura de la hoja.']};}
